      "readingAid": "eo",
      "pronunciation": "Close to the u in “sun.”",
      "audioText": "ㅓ",
      "forms": []
    },
    {
      "symbol": "ㅗ",
      "readingAid": "o",
      "pronunciation": "Like the o in “go,” but pure, without the glide at the end.",
      "audioText": "ㅗ",
      "forms": []
